import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './Adminproduct.css';
import PageTitle from '../PageTitle';
import Sidebar from './Sidebar';
import EditProductModal from './EditProductModal';

const AdminProduct = ({ onEdit, onDelete }) => {
  const [products, setProducts] = useState([]); // Ürünler state'i
  const [searchTerm, setSearchTerm] = useState(''); // Arama terimi
  const [selectedProductId, setSelectedProductId] = useState(null); // Seçilen ürün ID'si
  const [isModalOpen, setIsModalOpen] = useState(false); // Modal açık mı?

  // Backend'den ürünleri almak için useEffect kullanıyoruz
  useEffect(() => {
    axios
      .get('http://localhost:3001/api/products') // API URL'yi backend URL'ye göre düzeltiyoruz
      .then((response) => {
        setProducts(response.data); // Veriyi state'e set ediyoruz
      })
      .catch((error) => {
        console.error('Ürünler alınırken hata oluştu:', error);
      });
  }, []);  // Bu effect sadece bileşen ilk render olduğunda çalışır

  // Ürünleri arama
  const filteredProducts = products.filter(product =>
    product.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  // Düzenleme butonuna tıklandığında modalı aç
  const handleEdit = (productId) => {
    setSelectedProductId(productId);
    setIsModalOpen(true); // Modalı aç
  };

  // Modal kapandığında
  const handleCloseModal = () => {
    setIsModalOpen(false);
  };

  // Ürün güncellendikten sonra listeyi güncelle
  const handleSaveProduct = (updatedProduct) => {
    setProducts((prevProducts) =>
      prevProducts.map((product) =>
        product.id === updatedProduct.id ? updatedProduct : product
      )
    );
  };

  return (
    <>
      <PageTitle title="Ürünler" />
      <div className="admin-container">
        {/* Sidebar */}
        <Sidebar /> {/* Sidebar'ı buraya ekleyin */}

        <div className="admin-product-container">
          {/* Arama Çubuğu */}
          <input
            type="text"
            className="search-bar"
            placeholder="Ürün ara..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />

          {/* Ürün Tablosu */}
          <table className="admin-product-table">
            <thead>
              <tr>
                <th>Ürün Adı</th>
                <th>Ürün Kategorisi</th>
                <th>Ürün Açıklaması</th>
                <th>Ürün Fiyatı</th>
                <th>İşlemler</th>
              </tr>
            </thead>
            <tbody>
              {filteredProducts.length > 0 ? (
                filteredProducts.map((product) => (
                  <tr key={product._id}>
                    <td>{product.name}</td>
                    <td>{product.category}</td>
                    <td>{product.productdetails}</td>
                    <td>{product.price.toLocaleString()} TL</td>
                    <td>
                      <button onClick={() => handleEdit(product._id)} className="edit-button">
                        Düzenle
                      </button>
                      <button onClick={() => onDelete(product.id)} className="delete-button">
                        Sil
                      </button>
                    </td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan="5">Hiç ürün bulunamadı.</td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* EditProductModal Bileşeni */}
      <EditProductModal
        productId={selectedProductId}
        isOpen={isModalOpen}
        onClose={handleCloseModal}
        onSave={handleSaveProduct}
      />
    </>
  );
};

export default AdminProduct;
